// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }

    function testFuzz_property(address recipient1, uint256 amount1, address recipient2, uint256 amount2) public {
        vm.assume(recipient1 != address(0));
        vm.assume(recipient2 != address(0));
        vm.assume(recipient1 != recipient2);
        vm.assume(amount1 != amount2);
        c.newGrantProposal(recipient1, amount1);
        c.newGrantProposal(recipient2, amount2);
        // General rule: every newGrantProposal call increments proposalCount by one,
        // so after two calls the latest proposal id is 2 and its grant details are those of the second call.
        assertTrue(c.proposalCount() == 2 && mapGrantRecipient(2) == recipient2 && mapGrantAmount(2) == amount2);
    }

    function mapGrantRecipient(uint256 id) internal view returns (address) {
        (address recipient, ) = c.mapPID_grant(id);
        return recipient;
    }

    function mapGrantAmount(uint256 id) internal view returns (uint256) {
        (, uint256 amount) = c.mapPID_grant(id);
        return amount;
    }
}
